    "lf_spotlight_6": {
      "type": "lf-spotlight",
      "settings": {
        "scheme": "soft",
        "eyebrow": "Dispositif Hydrafacial portable",
        "heading": "Le soin n°1 des instituts, <em>chez vous</em>",
        "text": "Aspiration douce et eau micro-pulvérisée : il désincruste les pores, élimine les points noirs et hydrate la peau en une seule séance de 10 minutes.",
        "button_label": "Je veux l'Hydrafacial -50%",
        "image_url": "https://launchify.tech/products_images/dispositif-hydrafacial-portable-beaute-soins-launchify-424934.jpg",
        "image_alt": "Dispositif Hydrafacial portable",
        "button_link": "shopify://products/dispositif-hydrafacial-portable-copy-f97e5",
        "handle": "dispositif-hydrafacial-portable-copy"
      },
      "blocks": {
        "bullet_1": {
          "type": "bullet",
          "settings": {
            "text": "6 embouts pour chaque zone du visage"
          }
        },
        "bullet_2": {
          "type": "bullet",
          "settings": {
            "text": "3 niveaux d'aspiration, doux pour les peaux sensibles"
          }
        },
        "bullet_3": {
          "type": "bullet",
          "settings": {
            "text": "Rechargeable en USB, 60 minutes d'autonomie"
          }
        },
        "stat_4": {
          "type": "stat",
          "settings": {
            "value": "120 €",
            "label": "le prix d'une seule séance en institut"
          }
        },
        "stat_5": {
          "type": "stat",
          "settings": {
            "value": "49,99 €",
            "label": "pour un appareil utilisable à vie"
          }
        }
      },
      "block_order": [
        "bullet_1",
        "bullet_2",
        "bullet_3",
        "stat_4",
        "stat_5"
      ]
    },
    "lf_benefits_7": {
      "type": "lf-benefits",
      "settings": {
        "scheme": "light",
        "layout": "cards",
        "eyebrow": "Pourquoi nos clientes nous choisissent",
        "heading": "La technologie des instituts, <em>sans le prix</em>",
        "text": "Des appareils pensés pour être simples, sûrs et efficaces dès la première utilisation."
      },
      "blocks": {
        "benefit_1": {
          "type": "benefit",
          "settings": {
            "icon": "⚡",
            "title": "Résultats immédiats",
            "text": "Une différence visible dès la première séance, sans période d'adaptation."
          }
        },
        "benefit_2": {
          "type": "benefit",
          "settings": {
            "icon": "💸",
            "title": "Rentabilisé en 1 séance",
            "text": "Le prix d'un seul rendez-vous en institut, pour un appareil qui dure des années."
          }
        },
        "benefit_3": {
          "type": "benefit",
          "settings": {
            "icon": "🛡️",
            "title": "Doux pour la peau",
            "text": "Réglages progressifs adaptés aux peaux sensibles et réactives."
          }
        },
        "benefit_4": {
          "type": "benefit",
          "settings": {
            "icon": "🔋",
            "title": "Sans fil & rechargeable",
            "text": "Utilisez-les partout, à la maison comme en voyage."
          }
        }
      },
      "block_order": [
        "benefit_1",
        "benefit_2",
        "benefit_3",
        "benefit_4"
      ]
    },
    "lf_spotlight_8": {
      "type": "lf-spotlight",
      "settings": {
        "scheme": "light",
        "reverse": true,
        "eyebrow": "Spécial cheveux",
        "heading": "Un brushing de salon <em>en 10 minutes</em>",
        "text": "Le boucleur 5-en-1 sèche, lisse, donne du volume et boucle grâce à l'effet Coanda : l'air enroule automatiquement les mèches, sans chaleur extrême.",
        "button_label": "Découvrir le boucleur",
        "image_url": "https://images.unsplash.com/photo-1522337360788-8b13dee7a37e",
        "image_alt": "Femme se faisant coiffer",
        "button_link": "shopify://products/le-boucleur-5-en-1-a9c96",
        "handle": "le-boucleur-5-en-1"
      },
      "blocks": {
        "bullet_1": {
          "type": "bullet",
          "settings": {
            "text": "5 embouts interchangeables inclus"
          }
        },
        "bullet_2": {
          "type": "bullet",
          "settings": {
            "text": "Protège la fibre capillaire, moins de frisottis"
          }
        }
      },
      "block_order": [
        "bullet_1",
        "bullet_2"
      ]
    },
    "lf_manifesto_9": {
      "type": "lf-manifesto",
      "settings": {
        "scheme": "dark",
        "eyebrow": "Notre philosophie",
        "heading": "Prendre soin de soi <em>ne devrait pas être un luxe</em>",
        "text": "Nous rendons accessibles à toutes les soins réservés aux instituts. Même résultat, à la maison, quand vous le voulez.",
        "button_label": "Rejoindre le mouvement"
      }
    },
    "lf_faq_10": {
      "type": "lf-faq",
      "settings": {
        "scheme": "light",
        "eyebrow": "FAQ",
        "heading": "Vos questions, nos réponses"
      },
      "blocks": {
        "question_1": {
          "type": "question",
          "settings": {
            "question": "Les appareils conviennent-ils aux peaux sensibles ?",
            "answer": "<p>Oui. Chaque appareil dispose de plusieurs niveaux d'intensité : commencez au plus doux et augmentez progressivement.</p>"
          }
        },
        "question_2": {
          "type": "question",
          "settings": {
            "question": "Quand vais-je voir des résultats ?",
            "answer": "<p>La plupart de nos clientes constatent une différence dès la première utilisation, et un effet durable après 2 à 3 semaines.</p>"
          }
        },
        "question_3": {
          "type": "question",
          "settings": {
            "question": "Et si l'appareil ne me convient pas ?",
            "answer": "<p>Vous avez 30 jours pour l'essayer. S'il ne vous plaît pas, on vous rembourse.</p>"
          }
        },
        "question_4": {
          "type": "question",
          "settings": {
            "question": "Quels sont les délais de livraison ?",
            "answer": "<p>Les commandes passées avant 14h partent le jour même. Livraison offerte dès 35€.</p>"
          }
        }
      },
      "block_order": [
        "question_1",
        "question_2",
        "question_3",
        "question_4"
      ]
    }
  },
  "order": [
    "lf_hero_1",
    "lf_marquee_2",
    "lf_benefits_3",
    "lf_products_4",
    "lf_categories_5",
    "lf_spotlight_6",
